import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums for main items ---
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a single sword → base premium 100 G");
  it.todo("a single amulet → base premium 60 G");
  it.todo("a single staff → base premium 80 G");
  it.todo("a single potion → base premium 40 G");

  // --- Quote: components and the block of 3 alike ---
  it.todo("a single rune → base premium 25 G");
  it.todo("a single moonstone → base premium 25 G");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Quote: item-scope modifiers ---
  it.todo("a cursed sword adds a 50 % surcharge on its own base premium");
  it.todo("a sword with enchantment 5 adds a 30 % surcharge (threshold met)");
  it.todo("a sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("a cursed sword with enchantment 5 gets both surcharges");
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → 210 G before further modifiers and fee (curse applies to the cursed item only)",
  );

  // --- Quote: policy-scope modifiers ---
  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("the first insurance carries a 10 % initial assessment surcharge");
  it.todo("a second quote in the scenario receives a 15 % follow-up contract discount");
  it.todo("the first insurance surcharge still applies on a follow-up contract");

  // --- Quote: rounding ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate premium amounts are kept as fractions; only the final premium is rounded");

  // --- Quote: integration examples ---
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years) second quote, cursed steel sword enchantment 7 → premium 160 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible per damaged item)");

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold met)");

  // --- Claim: rounding ---
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Claim: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remaining cap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("two swords insured, a dragon attack damages both → each damage entry has its own deductible");
  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → rejected");

  // --- Errors ---
  it.todo("a quote with an unknown item type (broomstick) → rejected with an error");
  it.todo("a claim for an item not part of the policy (amulet damaged, only a sword insured) → rejected");
  it.todo("a claim with a damage entry of an unknown item type → rejected");
  it.todo("a claim with a damage entry of amount -200 → rejected");

  // --- CLI ---
  it.todo("the CLI reads a JSON scenario from stdin and writes { results } to stdout");
  it.todo("the CLI exits with a non-zero status and writes to stderr on an invalid scenario, with no results on stdout");
});

