export type QuoteResult = {
  premium: number;
};

export type ScenarioOutcome = {
  results: QuoteResult[];
};

type Item = { type: string };

type Scenario = {
  steps: { items: Item[] }[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const sumOfIndividualBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const basePremiumOf = (items: Item[]): number => {
  if (items.length === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;

  return sumOfIndividualBasePremiums(items);
};

const quotePremium = (items: Item[]): number => {
  const base = basePremiumOf(items);
  const withFirstInsuranceSurcharge = base + base * FIRST_INSURANCE_SURCHARGE;

  return Math.ceil(withFirstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

