export type QuoteResult = {
  premium: number;
};

export type ScenarioOutcome = {
  results: QuoteResult[];
};

type Item = { type: string };

type Scenario = {
  steps: { items: Item[] }[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const ALIKE_BLOCK_SIZE = 3;
const ALIKE_BLOCK_PREMIUM = 60;

type AlikeGroup = [type: string, count: number];

const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
  const countByType = new Map<string, number>();

  for (const item of items) {
    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
  }

  return [...countByType];
};

const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;

  return count * BASE_PREMIUMS[type];
};

const basePremiumOf = (items: Item[]): number =>
  groupAlikeItems(items)
    .map(basePremiumOfGroup)
    .reduce((total, groupPremium) => total + groupPremium, 0);

const quotePremium = (items: Item[]): number => {
  const base = basePremiumOf(items);
  const withFirstInsuranceSurcharge = base + base * FIRST_INSURANCE_SURCHARGE;

  return Math.ceil(withFirstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

