export type QuoteResult = {
  premium: number;
};

export type ScenarioOutcome = {
  results: QuoteResult[];
};

type Item = { type: string; cursed?: boolean };

type Scenario = {
  steps: { items: Item[] }[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const ALIKE_BLOCK_SIZE = 3;
const ALIKE_BLOCK_PREMIUM = 60;

type AlikeGroup = [type: string, count: number];

const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
  const countByType = new Map<string, number>();

  for (const item of items) {
    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
  }

  return [...countByType];
};

const ownBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;

  return count * BASE_PREMIUMS[type];
};

/**
 * The policy base premium: the sum of the item base premiums, with the
 * alike-block discount applied. Policy-scope modifiers are percentages OF
 * THIS amount — never of a total that already includes item surcharges.
 */
const policyBasePremiumOf = (items: Item[]): number =>
  groupAlikeItems(items)
    .map(basePremiumOfGroup)
    .reduce((total, groupPremium) => total + groupPremium, 0);

/**
 * Item-scope surcharges: each is a percentage of the affected item's OWN base
 * premium, independent of the policy base and of the alike-block discount.
 */
const itemSurchargesOf = (items: Item[]): number =>
  items
    .filter((item) => item.cursed)
    .reduce((total, item) => total + ownBasePremiumOf(item) * CURSE_SURCHARGE, 0);

/**
 * Policy-scope surcharges: each is a percentage of the policy base premium.
 */
const policySurchargesOn = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE;

const quotePremium = (items: Item[]): number => {
  const policyBase = policyBasePremiumOf(items);
  const premium =
    policyBase +
    itemSurchargesOf(items) +
    policySurchargesOn(policyBase) +
    PROCESSING_FEE;

  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

