const itemSurchargesOf = (items: Item[]): number =>
  items.reduce((total, item) => total + ownBasePremiumOf(item) * surchargeRateOf(item), 0);

/**
 * Policy-scope surcharges: each is a percentage of the policy base premium.
 */
const policySurchargesOn = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE;

const quotePremium = (items: Item[]): number => {
  const policyBase = policyBasePremiumOf(items);
  const premium =
    policyBase +
    itemSurchargesOf(items) +
    policySurchargesOn(policyBase) +
    PROCESSING_FEE;

  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

