const insuranceSumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const payoutForDamage = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const settleClaim = (claim: ClaimStep, steps: Step[]): ClaimResult => {
  const policy = steps[claim.policy] as QuoteStep;
  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
  const payout = claim.incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage),
    0,
  );

  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, stepIndex) =>
    isQuoteStep(step)
      ? {
          premium: quotePremium(step.items, {
            customer: scenario.customer,
            isFollowUpContract: hasPrecedingStep(stepIndex),
          }),
        }
      : settleClaim(step, scenario.steps),
  ),
});

